const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.circle}"/></svg>`;
function icons(parent=document){parent.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}icons();
const definitions=[['用例编写','测试部门','TEST_Test_Case','从需求整理测试点，输出精简、可追溯的测试用例。'],['代码静态检测','测试部门','TEST_Test_Codetest','按用例检查分支代码，区分静态证据、可达缺陷与证据缺口。'],['缺陷归因','测试部门','缺陷归因规则','核对共同根因与影响范围，保留逐条证据和待确认问题。'],['缺陷提单','测试部门','TEST_Test_Feishu','依据确认的根因准备缺陷草稿，对外发布前由负责人核对。'],['代码回归','测试部门','代码回归规则','核对修复代码与原缺陷证据，最终状态由负责人决定。']];
const nodes=definitions.map(([name,dept,skill,description])=>({name,dept,skill,description,input:'',saved:'',savedSkill:skill,auto:false,status:'idle',logs:[],tab:'config',file:''}));
let index=0,selectedSkill='',toastTimer,runTimer,savePending=false;const n=()=>nodes[index];
function toast(message){const el=$('#toast');clearTimeout(toastTimer);el.textContent=message;el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,3200)}
function log(message,node=n()){node.logs.unshift({message,time:new Date().toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})});if(node===n())renderLogs()}
function renderLogs(){ $('#logs').innerHTML=n().logs.length?n().logs.map(e=>`<li>${esc(e.message)}<time>${esc(e.time)} · 原型操作</time></li>`).join(''):'<li class="log-empty">暂无操作记录<p>保存、执行和确认将在这里留下记录。</p></li>' }
function renderFlow(){ $('#flow').innerHTML=nodes.map((node,i)=>`<button class="flow-node" data-node="${i}" aria-current="${i===index?'step':'false'}" aria-label="${i+1} ${esc(node.name)}${i===index?'，当前节点':''}"><span class="node-ordinal">${node.status==='done'?icon('check'):String(i+1).padStart(2,'0')}</span><span><strong>${esc(node.name)}</strong><small>${esc(node.dept)}</small></span></button>${i<nodes.length-1?'<span class="flow-arrow">'+icon('arrow')+'</span>':''}`).join('') }
function dirty(){return n().input!==n().saved||n().skill!==n().savedSkill}
function updatePreparation(){const has=n().input.trim().length>0;$('#input-count').textContent=n().input.length+' 字';$('#input-check').classList.toggle('ready',has);$('#input-check').innerHTML=icon(has?'check':'circle');$('#save').disabled=!dirty()||savePending;$('#save-status').innerHTML=icon(dirty()?'circle':'check')+(dirty()?'有未保存修改':'已与本次预览配置同步');$('#check-skill').textContent=n().skill;$('#skill-name').textContent=n().skill}
function switchTab(tab){n().tab=tab;$('#config-view').hidden=tab!=='config';$('#result-view').hidden=tab!=='result';$('#config-tab').setAttribute('aria-selected',tab==='config');$('#result-tab').setAttribute('aria-selected',tab==='result')}
function render(){renderFlow();$('#node-title').textContent=n().name;$('#node-position').textContent='NODE '+String(index+1).padStart(2,'0')+' / 05';$('#task-description').textContent=n().description;$('#task-input').value=n().input;$('#next-node').innerHTML=esc(nodes[index+1]?.name||'本流程结束')+icon('arrow');$('#auto-switch').setAttribute('aria-checked',n().auto);$('#auto-switch').disabled=index===nodes.length-1;$('#auto-label').textContent=n().auto?'自动衔接':'手动继续';$('#auto-hint').textContent=n().auto?'审核仍需人工确认；本原型仅演示节点衔接。':'完成审核后，由你决定何时进入下一节点。';$('#scenario').value=n().status;$('#task-input').removeAttribute('aria-invalid');$('#input-hint').innerHTML=icon('info')+'输入只属于当前节点；切换节点保留草稿，运行使用已保存配置。';$('#input-hint').style.color='';renderLogs();updatePreparation();renderStatus();switchTab(n().tab)}
function renderStatus(){const status=n().status,labels={idle:'准备配置',running:'正在执行',waiting:'待人工确认',failed:'执行失败',done:'审核通过'};$('#node-state').textContent=labels[status];$('#node-state').className='state-tag '+status;$('#scenario').value=status;
const config={idle:['准备好资料，开始本节点','本页只演示交互，不调用模型或外部工具。','预览运行','play'],running:['正在演示执行过程','正在处理任务。你可以切换节点查看，任务不会因此重启。','演示执行中','circle'],waiting:['输出已就绪，等待你确认','请核对正文、证据与缺口；执行完成不等于审核通过。','确认本节点','check'],failed:['执行没有完成，可保留输入重试','查看失败说明，配置与草稿已保留；不会自动重试。','重新预览','arrow'],done:[index===4?'所有节点已走完':'当前节点已确认',index===4?'此处仅演示交付结束状态。':'手动继续至下一节点，已确认节点的结果继续保留。',index===4?'查看完成说明':'前往下一节点','arrow']}[status];
$('#next-title').textContent=config[0];$('#next-hint').textContent=config[1];$('#run').innerHTML=icon(config[3],status==='running'?'spinner':'')+'<span>'+config[2]+'</span>';$('#run').disabled=status==='running';
const info={idle:['document','尚未开始运行','在节点配置中准备资料后，点击“预览运行”体验完整交互。'],running:['circle','正在执行 · 演示','模型未实际调用，这里只预览等待反馈和布局保持。'],waiting:['clock','待人工确认 · 演示','以下仅为交付结构示例，不是真实 AI 生成的测试用例。'],failed:['warning','执行失败 · 演示','模拟连接中断。实际产品应展示真实错误来源与可恢复操作。'],done:['check','本节点已确认 · 演示','负责人确认与执行完成分开记录，不自动改变真实外部状态。']}[status];
$('#result-content').innerHTML=`<div class="result-state ${status}">${icon(info[0],status==='running'?'spinner':'')}<div><h4>${info[1]}</h4><p>${info[2]}</p></div></div><div class="result-detail"><h4>${status==='failed'?'可恢复操作':'交付结构示例'}</h4>${status==='failed'?'<p>保留当前输入和 Skill，核对连接后手动重试。重试不自动提交 Bug、不改变审核状态。</p>':'<ul><li>交付正文：根据当前节点任务组织内容。</li><li>证据依据：保留需求来源、代码引用或产物链接。</li><li>覆盖缺口：明确未验证内容与待确认问题。</li></ul>'}</div>`;
}
$('#flow').addEventListener('click',e=>{const target=e.target.closest('[data-node]');if(!target)return;index=Number(target.dataset.node);render();$('#node-title').setAttribute('tabindex','-1');$('#node-title').focus({preventScroll:true})});
$('#task-input').addEventListener('input',e=>{n().input=e.target.value;updatePreparation();if(e.target.hasAttribute('aria-invalid')){$('#input-hint').innerHTML=icon('info')+'输入只属于当前节点；切换节点保留草稿，运行使用已保存配置。';$('#input-hint').style.color='';e.target.removeAttribute('aria-invalid')}});
$$('[data-source]').forEach(el=>el.addEventListener('click',()=>{const expanded=el.getAttribute('aria-expanded')!=='true';el.setAttribute('aria-expanded',expanded);$('#source-'+el.dataset.source).hidden=!expanded}));
$('#source-upload').addEventListener('change',e=>{$('#file-name').textContent=e.target.files[0]?.name||'TXT、Markdown、DOCX、XLSX';toast('仅展示已选择的文件，不上传、不读取内容')});
async function save(){if(savePending||!dirty())return;const node=n();savePending=true;const button=$('#save');button.disabled=true;button.setAttribute('aria-busy','true');button.innerHTML=icon('circle','spinner')+'保存中';await new Promise(r=>setTimeout(r,500));node.saved=node.input;node.savedSkill=node.skill;savePending=false;button.removeAttribute('aria-busy');button.innerHTML=icon('check')+'保存配置';log('保存节点配置（原型会话）',node);if(node===n())updatePreparation();toast('已保存至本次预览，不写入真实项目')}
$('#save').addEventListener('click',save);
$('#auto-switch').addEventListener('click',()=>{n().auto=!n().auto;render();log('切换为'+(n().auto?'自动衔接':'手动继续')+'（演示）')});
$('#config-tab').addEventListener('click',()=>switchTab('config'));$('#result-tab').addEventListener('click',()=>switchTab('result'));
$$('[role=tab]').forEach(tab=>tab.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const next=tab.id==='config-tab'?$('#result-tab'):$('#config-tab');next.click();next.focus()}}));
$('#run').addEventListener('click',async()=>{const node=n();if(node.status==='waiting'){node.status='done';log('人工确认本节点（演示）');if(node.auto&&index<4){index++;render();toast('已进入下一节点；下一步执行仍需满足实际门禁');return}render();return}if(node.status==='done'){if(index<4){index++;render()}else toast('流程结束状态仅为演示，不生成真实交付');return}
if(!node.input.trim()){switchTab('config');$('#task-input').setAttribute('aria-invalid','true');$('#input-hint').innerHTML=icon('warning')+'请补充任务说明或输入资料后再预览运行。';$('#input-hint').style.color='var(--red)';$('#task-input').focus();return}await save();if(node!==n()){toast('当前节点已变化，请在目标节点重新操作');return}node.status='running';node.tab='result';log('开始演示运行（不调用模型）');render();clearTimeout(runTimer);runTimer=setTimeout(()=>{node.status='waiting';log('演示输出就绪，等待人工确认',node);if(node===n())render();toast('演示执行已结束，请查看交付结构并人工确认')},1600)});
$('#scenario').addEventListener('change',e=>{clearTimeout(runTimer);n().status=e.target.value;n().tab=e.target.value==='idle'?'config':'result';log('切换演示状态：'+e.target.selectedOptions[0].textContent);render()});
const skillExamples=[['TEST_Test_Case','需求拆解、覆盖点与测试用例'],['TEST_Test_Codetest','逐用例静态代码检测与证据边界'],['团队自定义 Skill','自行定义输入、输出和人工审核规则']];
function renderSkills(){const query=$('#skill-search').value.trim().toLowerCase();$('#skill-list').innerHTML=skillExamples.filter(([name,desc])=>(name+' '+desc).toLowerCase().includes(query)).map(([name,desc])=>`<button class="skill-option" data-skill="${esc(name)}" aria-pressed="${name===selectedSkill}"><span><strong>${esc(name)}</strong><small>${esc(desc)}</small></span>${icon(name===selectedSkill?'check':'circle')}</button>`).join('')||'<p class="subtle">未找到匹配的示例 Skill。</p>'}
const dialog=$('#skill-dialog');function openSkills(){selectedSkill=n().skill;$('#skill-search').value='';renderSkills();dialog.showModal();$('#skill-search').focus()}$$('[data-open-skill]').forEach(el=>el.addEventListener('click',openSkills));$('[data-close]').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{const rect=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom))dialog.close()});$('#skill-search').addEventListener('input',renderSkills);$('#skill-list').addEventListener('click',e=>{const target=e.target.closest('[data-skill]');if(target){selectedSkill=target.dataset.skill;renderSkills()}});$('#apply-skill').addEventListener('click',()=>{n().skill=selectedSkill;log('选择 Skill：'+selectedSkill+'（示例）');updatePreparation();dialog.close();toast('已选择 '+selectedSkill+'，保存后用于本次预览')});
function showExplanation(){const el=document.createElement('dialog');el.setAttribute('aria-label','交互设计说明');el.innerHTML='<div class="drawer-head"><div><div class="eyebrow">INTERACTION DESIGN</div><h2>交互设计重点</h2></div><button class="icon-button" aria-label="关闭">'+icon('close')+'</button></div><div class="drawer-body result-detail"><h4>清楚知道该做什么</h4><p>节点配置、执行、人工确认与继续使用各自明确的状态和主操作。</p><h4>输入不丢，操作不跳</h4><p>节点草稿各自保留，保存有反馈；弹窗与吸顶保持布局和键盘焦点。</p><h4>复杂内容按需展开</h4><p>需求来源默认收起，Skill 在侧抽屉中选择，执行结果独立查看。</p><h4>保留人工决策</h4><p>执行完成不等于审核通过，自动衔接也不会省掉证据与人工门禁。</p><h4>流程设置</h4><p>当前可在右侧体验自动衔接开关与五种状态；结构编辑继续使用独立编辑器，不混入日常操作。</p><h4>原型边界</h4><p>本页不连接数据库、模型、飞书或真实项目，所有状态均为内存演示。</p></div>';document.body.append(el);el.querySelector('button').onclick=()=>el.close();el.addEventListener('click',e=>{if(e.target===el&&e.clientX<el.getBoundingClientRect().left)el.close()});el.addEventListener('close',()=>el.remove());el.showModal()}
$('#help').addEventListener('click',showExplanation);$('#edit-flow').addEventListener('click',showExplanation);$$('[data-view],[data-dept]').forEach(el=>el.addEventListener('click',()=>{if(el.dataset.view==='workflow'){index=0;render();toast('已返回工作流首节点')}else toast('这是节点工作区交互稿，其他页面仍使用现有平台入口')}));document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'&&!document.querySelector('dialog[open]')){e.preventDefault();save()}});render();
